package orders

import (
	"context"
	"os"
	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/sns"
)

var client *sns.Client

func publish(ctx context.Context, topic string, msg string) {
	client.Publish(ctx, &sns.PublishInput{TopicArn: aws.String(topic), Message: aws.String(msg)})
}

func PublishOrder(ctx context.Context, msg string) {
	publish(ctx, os.Getenv("ORDERS_TOPIC"), msg)
}

